def enrol(student, count, capacity):
    if len(student) != 4 or student[0] != "S" or not student[1:].isdigit():
        return count, "INVALID"
    if count >= capacity:
        return count, "FULL"
    return count + 1, "ACCEPT"
count = 0
for student in ["S001", "bad", "S002", "S003"]:
    count, message = enrol(student, count, 2)
    print(student, count, message)
assert enrol("S004", 2, 2) == (2, "FULL")
assert enrol("S004", 1, 2) == (2, "ACCEPT")
assert enrol("", 0, 2) == (0, "INVALID")

PASS_MARK = 50

def statistics(values):
    if not values:
        return None
    total = 0
    passed = 0
    smallest = values[0]
    largest = values[0]
    for value in values:
        total += value
        if value >= PASS_MARK:
            passed += 1
        if value < smallest:
            smallest = value
        if value > largest:
            largest = value
    return (smallest, largest, total / len(values), passed)

def linear_search(values, target):
    for i in range(len(values)):
        if values[i] == target:
            return i
    return -1

def nondecreasing(values):
    for i in range(1, len(values)):
        if values[i] < values[i - 1]:
            return False
    return True

def valid_code(code):
    return len(code) == 6 and code[:2] == "HK" and code[2:].isdigit()

print(statistics([40, 60, 80]))
print(linear_search([40, 60, 80], 60))
print(nondecreasing([2, 2, 5, 4]))
print(valid_code("HK0123"), "HK0123"[2:6])
assert statistics([]) is None
assert statistics([-8, -3, -5]) == (-8, -3, -16/3, 0)
assert statistics([50]) == (50, 50, 50.0, 1)
assert linear_search([7, 7], 7) == 0
assert linear_search([], 7) == -1
assert linear_search([1, 2], 9) == -1
assert nondecreasing([])
assert nondecreasing([2, 2, 5])
assert not nondecreasing([2, 2, 5, 4])
assert valid_code("HK0123")
assert not valid_code("")
assert not valid_code("HK12X3")

