def linear_search(a, target):
    for i in range(len(a)):
        if a[i] == target:
            return i
    return -1

def binary_search(a, target):
    low, high = 0, len(a) - 1
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == target:
            return mid
        if a[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def bubble(a):
    a = a[:]
    for end in range(len(a) - 1, 0, -1):
        changed = False
        for j in range(end):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                changed = True
        if not changed:
            break
    return a

def insertion(a):
    a = a[:]
    for i in range(1, len(a)):
        key = a[i]
        j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = key
    return a

def selection(a):
    a = a[:]
    for i in range(len(a) - 1):
        smallest = i
        for j in range(i + 1, len(a)):
            if a[j] < a[smallest]:
                smallest = j
        if smallest != i:
            a[i], a[smallest] = a[smallest], a[i]
    return a

def merge(a, b):
    i, j = 0, 0
    result = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    return result + a[i:] + b[j:]

for sample in [[], [3], [3,1,2], [2,2,-1], [5,4,3,2,1]]:
    expected = sorted(sample)
    assert bubble(sample) == expected
    assert insertion(sample) == expected
    assert selection(sample) == expected
    print(sample, expected)
assert binary_search([2,5,8,12,16,23,38],23) == 5
assert binary_search([],23) == -1
assert binary_search([2,5,8],6) == -1
assert merge([1,4,7],[2,3,8]) == [1,2,3,4,7,8]
assert merge([],[-2,1]) == [-2,1]
assert merge([1,1],[1]) == [1,1,1]
assert linear_search([7,7],7) == 0
assert linear_search([],7) == -1
assert linear_search([1,2],9) == -1
